package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.zip.ZipException;
import org.apache.commons.compress.utils.BufferUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class Zip64ExtendedInformationExtraField_parseFromLocalFileData_TriageGen2Test {

    private static final int DWORD = 4;
    private static final int WORD = 2;

    @Test
    public void testParse_LengthZero() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[0];
        // Should return immediately without throwing exception or setting values
        field.parseFromLocalFileData(buffer, 0, 0);
        assertNull(field.getSize());
        assertNull(field.getCompressedSize());
    }

    @Test(expected = ZipException.class)
    public void testParse_TooShort() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] buffer = new byte[6];
        // length < 2 * DWORD (8)
        field.parseFromLocalFileData(buffer, 0, 6);
    }

    @Test
    public void testParse_MinimumRequiredFields() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        int length = 2 * DWORD;
        ByteBuffer bb = ByteBuffer.allocate(length);
        bb.putInt(100); // size
        bb.putInt(200); // compressedSize
        byte[] buffer = bb.array();

        field.parseFromLocalFileData(buffer, 0, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(200L, field.getCompressedSize().longValue());
        assertNull(field.getRelativeHeaderOffset());
        assertNull(field.getDiskStartNumber());
    }

    @Test
    public void testParse_WithRelativeHeaderOffset() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // 2 * DWORD + 1 * DWORD = 12
        int length = 3 * DWORD;
        ByteBuffer bb = ByteBuffer.allocate(length);
        bb.putInt(100);      // size
        bb.putInt(200);      // compressedSize
        bb.putInt(300);      // relativeHeaderOffset
        byte[] buffer = bb.array();

        field.parseFromLocalFileData(buffer, 0, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(200L, field.getCompressedSize().longValue());
        assertEquals(300L, field.getRelativeHeaderOffset().longValue());
        assertNull(field.getDiskStartNumber());
    }

    @Test
    public void testParse_WithDiskStart() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // 2 * DWORD + 1 * DWORD + 1 * WORD = 14
        int length = 3 * DWORD + WORD;
        ByteBuffer bb = ByteBuffer.allocate(length);
        bb.putInt(100);      // size
        bb.putInt(200);      // compressedSize
        bb.putInt(300);      // relativeHeaderOffset
        bb.putShort((short) 5); // diskStart
        byte[] buffer = bb.array();

        field.parseFromLocalFileData(buffer, 0, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(200L, field.getCompressedSize().longValue());
        assertEquals(300L, field.getRelativeHeaderOffset().longValue());
        assertEquals(5L, field.getDiskStartNumber().longValue());
    }

    @Test
    public void testParse_WithOffset() throws ZipException {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        int length = 2 * DWORD;
        int offset = 4;
        ByteBuffer bb = ByteBuffer.allocate(offset + length);
        bb.putInt(0); // padding
        bb.putInt(100); // size at offset 4
        bb.putInt(200); // compressedSize at offset 8
        byte[] buffer = bb.array();

        field.parseFromLocalFileData(buffer, offset, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(200L, field.getCompressedSize().longValue());
    }

    @Test
    public void testParse_RemainingExactlyWord() throws ZipException {
        // Test the branch where remaining >= WORD but < DWORD (if logic allowed, 
        // but here remaining is checked sequentially)
        // Logic flow: if (remaining >= DWORD) { ... } if (remaining >= WORD) { ... }
        // To hit the second if but not the first, remaining must be < DWORD and >= WORD.

        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // 2 * DWORD + WORD = 10
        int length = 2 * DWORD + WORD;
        ByteBuffer bb = ByteBuffer.allocate(length);
        bb.putInt(100);
        bb.putInt(200);
        // remaining is 2. 2 < 4, so relativeHeaderOffset is skipped.
        // 2 >= 2, so diskStart is processed.
        bb.putShort((short) 7);
        byte[] buffer = bb.array();

        field.parseFromLocalFileData(buffer, 0, length);

        assertEquals(100L, field.getSize().longValue());
        assertEquals(200L, field.getCompressedSize().longValue());
        assertNull(field.getRelativeHeaderOffset());
        assertEquals(7L, field.getDiskStartNumber().longValue());
    }
}
